matches=[]
for base in ['/home/ubuntu/.local/share/prime-agent','/home/ubuntu/continual-arc-baselines/.workbench']:
  for root,dirs,files in os.walk(base):
    dirs[:] = [d for d in dirs if d not in ['node_modules','.git']]
